use std :: path :: { Path , PathBuf } ; use std :: sync :: Arc ; use anyhow :: Context ; use forge_app :: domain :: Skill ; use forge_app :: { EnvironmentInfra , FileInfoInfra , FileReaderInfra , Walker , WalkerInfra } ; use forge_domain :: SkillRepository ; use futures :: future :: join_all ; use gray_matter :: Matter ; use gray_matter :: engine :: YAML ; use serde :: Deserialize ; use forge_config :: ForgeConfig ; use forge_infra :: ForgeInfra ; use pretty_assertions :: assert_eq ; use super :: * ; impl < I : FileInfoInfra + EnvironmentInfra + FileReaderInfra + WalkerInfra > ForgeSkillRepository < I > { # [doc = " Loads skills from a specific directory by listing subdirectories first,"] # [doc = " then reading SKILL.md from each subdirectory if it exists"] async fn load_skills_from_dir (& self , dir : & std :: path :: Path) -> anyhow :: Result < Vec < Skill > > { if ! self . infra . exists (dir) . await ? { return Ok (vec ! []) ; } let walker = Walker :: unlimited () . cwd (dir . to_path_buf ()) . max_depth (1_usize) . max_breadth (usize :: MAX) ; let entries = self . infra . walk (walker) . await . with_context (| | format ! ("Failed to list directory: {}" , dir . display ())) ? ; let mut subdirs : Vec < _ > = entries . into_iter () . filter_map (| walked | { if walked . is_dir () && ! walked . path . is_empty () { Some (dir . join (& walked . path)) } else { None } }) . collect () ; sort_paths (& mut subdirs) ; let futures = subdirs . into_iter () . map (| subdir | { let infra = Arc :: clone (& self . infra) ; async move { let skill_path = subdir . join ("SKILL.md") ; if infra . exists (& skill_path) . await ? { match infra . read_utf8 (& skill_path) . await { Ok (content) => { let path_str = skill_path . display () . to_string () ; let skill_name = subdir . file_name () . and_then (| s | s . to_str ()) . unwrap_or ("unknown") . to_string () ; let walker = Walker :: unlimited () . cwd (subdir . clone ()) ; let mut resources = infra . walk (walker) . await . unwrap_or_default () . into_iter () . filter_map (| walked | { if ! walked . is_dir () { let full_path = subdir . join (& walked . path) ; if full_path . file_name () != skill_path . file_name () { Some (full_path) } else { None } } else { None } }) . collect :: < Vec < _ > > () ; sort_paths (& mut resources) ; if let Some (skill) = extract_skill (& path_str , & content) { Ok (Some (skill . resources (resources))) } else { Ok (Some (Skill :: new (skill_name , content , String :: new ()) . path (path_str) . resources (resources) ,)) } } Err (e) => { tracing :: warn ! ("Failed to read skill file {}: {}" , skill_path . display () , e) ; Ok (None) } } } else { Ok (None) } } }) ; let results = join_all (futures) . await ; let skills : Vec < Skill > = results . into_iter () . filter_map (| result : anyhow :: Result < Option < Skill > > | result . ok () . flatten ()) . collect () ; Ok (skills) } # [doc = " Renders a skill's command field with environment context"] # [doc = ""] # [doc = " # Arguments"] # [doc = " * `skill` - The skill to render"] # [doc = " * `env` - The environment containing path informations"] fn render_skill (& self , skill : Skill , env : & forge_domain :: Environment) -> Skill { let global = env . global_skills_path () . display () . to_string () ; let agents = env . agents_skills_path () . map (| p | p . display () . to_string ()) . unwrap_or_default () ; let local = env . local_skills_path () . display () . to_string () ; let rendered = skill . command . replace ("{{global_skills_path}}" , & global) . replace ("{{agents_skills_path}}" , & agents) . replace ("{{local_skills_path}}" , & local) ; skill . command (rendered) } }